import{_ as t,o as r,c as a,al as o}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Flight Controller Porting Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/hardware/porting_guide.md","filePath":"en/hardware/porting_guide.md"}'),i={name:"en/hardware/porting_guide.md"};function n(l,e,s,d,h,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="flight-controller-porting-guide" tabindex="-1">Flight Controller Porting Guide <a class="header-anchor" href="#flight-controller-porting-guide" aria-label="Permalink to &quot;Flight Controller Porting Guide&quot;">​</a></h1><p>This topic is for developers who want to port PX4 to work with <em>new</em> flight controller hardware.</p><h2 id="px4-architecture" tabindex="-1">PX4 Architecture <a class="header-anchor" href="#px4-architecture" aria-label="Permalink to &quot;PX4 Architecture&quot;">​</a></h2><p>PX4 consists of two main layers: The <a href="./../middleware/">board support and middleware layer</a> on top of the host OS (NuttX, Linux or any other POSIX platform like Mac OS), and the applications (Flight Stack in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/src/modules" target="_blank" rel="noreferrer">src/modules</a>). Please reference the <a href="./../concept/architecture">PX4 Architectural Overview</a> for more information.</p><p>This guide is focused only on the host OS and middleware as the applications/flight stack will run on any board target.</p><h2 id="flight-controller-configuration-file-layout" tabindex="-1">Flight Controller Configuration File Layout <a class="header-anchor" href="#flight-controller-configuration-file-layout" aria-label="Permalink to &quot;Flight Controller Configuration File Layout&quot;">​</a></h2><p>Board startup and configuration files are located under <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/" target="_blank" rel="noreferrer">/boards</a> in each board&#39;s vendor-specific directory (i.e. <strong>boards/<em>VENDOR</em>/<em>MODEL</em>/</strong>).</p><p>For example, for FMUv5:</p><ul><li>(All) Board-specific files: <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/px4/fmu-v5" target="_blank" rel="noreferrer">/boards/px4/fmu-v5</a>.</li><li>Build configuration: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/default.px4board" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/default.px4board</a>.</li><li>Board-specific initialisation file: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/init/rc.board_defaults" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/init/rc.board_defaults</a><ul><li>A board-specific initialisation file is automatically included in startup scripts if found under the boards directory at <strong>init/rc.board</strong>.</li><li>The file is used to start sensors (and other things) that only exist on a particular board. It may also be used to set a board&#39;s default parameters, UART mappings, and any other special cases.</li><li>For FMUv5 you can see all the Pixhawk 4 sensors being started, and it also sets a larger LOGGER_BUF.</li></ul></li></ul><h2 id="host-operating-system-configuration" tabindex="-1">Host Operating System Configuration <a class="header-anchor" href="#host-operating-system-configuration" aria-label="Permalink to &quot;Host Operating System Configuration&quot;">​</a></h2><p>This section describes the purpose and location of the configuration files required for each supported host operating system to port them to new flight controller hardware.</p><h3 id="nuttx" tabindex="-1">NuttX <a class="header-anchor" href="#nuttx" aria-label="Permalink to &quot;NuttX&quot;">​</a></h3><p>See <a href="./porting_guide_nuttx">NuttX Board Porting Guide</a>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Linux boards do not include the OS and kernel configuration. These are already provided by the Linux image available for the board (which needs to support the inertial sensors out of the box).</p><ul><li><a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/raspberrypi/default.px4board" target="_blank" rel="noreferrer">boards/px4/raspberrypi/default.px4board</a> - RPi cross-compilation. </li></ul><h2 id="middleware-components-and-configuration" tabindex="-1">Middleware Components and Configuration <a class="header-anchor" href="#middleware-components-and-configuration" aria-label="Permalink to &quot;Middleware Components and Configuration&quot;">​</a></h2><p>This section describes the various middleware components, and the configuration file updates needed to port them to new flight controller hardware.</p><h3 id="qurt-hexagon" tabindex="-1">QuRT / Hexagon <a class="header-anchor" href="#qurt-hexagon" aria-label="Permalink to &quot;QuRT / Hexagon&quot;">​</a></h3><ul><li>The start script is located in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/posix-configs" target="_blank" rel="noreferrer">posix-configs/</a>. </li><li>The OS configuration is part of the default Linux image (TODO: Provide location of LINUX IMAGE and flash instructions).</li><li>The PX4 middleware configuration is located in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards" target="_blank" rel="noreferrer">src/boards</a>. TODO: ADD BUS CONFIG</li></ul><h2 id="rc-uart-wiring-recommendations" tabindex="-1">RC UART Wiring Recommendations <a class="header-anchor" href="#rc-uart-wiring-recommendations" aria-label="Permalink to &quot;RC UART Wiring Recommendations&quot;">​</a></h2><p>It is generally recommended to connect RC via separate RX and TX pins to the microcontroller. If however RX and TX are connected together, the UART has to be put into singlewire mode to prevent any contention. This is done via board config and manifest files. One example is <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/src/manifest.c" target="_blank" rel="noreferrer">px4fmu-v5</a>. </p><h2 id="getting-your-board-supported" tabindex="-1">Getting Your Board Supported <a class="header-anchor" href="#getting-your-board-supported" aria-label="Permalink to &quot;Getting Your Board Supported&quot;">​</a></h2><p>This page covers the <em>technical</em> work of porting PX4 to new hardware. The <em>process</em> for getting that port reviewed, merged, and listed on the PX4 website, including board IDs, USB VID/PID, flight-test evidence, and maintenance expectations, is documented separately:</p><ul><li><a href="./../hardware/board_support_guide">Manufacturer&#39;s PX4 Board Support Guide</a></li></ul><p>In short: build your own firmware target based on PX4, demonstrate stable flight on the current release, and open a pull request with your board support code, documentation, and flight logs. The board support guide explains each step.</p><p>The PX4 project supports and maintains the <a href="./../hardware/reference_design">FMU standard reference hardware</a> and any boards compatible with the standard, including the <a href="./../flight_controller/pixhawk_series">Pixhawk series</a> (see the <a href="./../flight_controller/">full list of supported hardware</a>). Boards merged into PX4 benefit from a port in the repository, firmware builds accessible from <em>QGroundControl</em>, compatibility with the rest of the ecosystem, and automated CI checks.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The cost of maintaining a port is proportional to how far it diverges from the standard. Consider that cost before deviating: staying close to the reference design lets you benefit from day-to-day PX4 development with minimal maintenance burden.</p></div><p>Manufacturers are responsible for keeping their port up to date and working across PX4 releases. The PX4 project reserves the right to refuse or remove ports that do not meet the project&#39;s requirements, and all contributors are expected to follow the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a>.</p><h2 id="related-information" tabindex="-1">Related Information <a class="header-anchor" href="#related-information" aria-label="Permalink to &quot;Related Information&quot;">​</a></h2><ul><li><a href="./../middleware/drivers">Device Drivers</a> - How to support new peripheral hardware (device drivers)</li><li><a href="./../dev_setup/building_px4">Building the Code</a> - How to build source and upload firmware</li><li>Supported Flight Controllers: <ul><li><a href="./../flight_controller/">Autopilot Hardware</a></li><li><a href="https://github.com/PX4/PX4-Autopilot/#supported-hardware" target="_blank" rel="noreferrer">Supported boards list</a> (Github) - Boards for which PX4-Autopilot has specific code</li></ul></li><li><a href="./../peripherals/">Supported Peripherals</a></li></ul>',31)])])}const f=t(i,[["render",n]]);export{c as __pageData,f as default};
